/// CRC-32 of the Apache licence text as ACE's own archives decode it (an independent check of the ARC LZW decoders).
private let arcLicenseCRC32: UInt32 = 0x7b5d_04bc

private func arcWork<T>(_ body: (URL) throws -> T) rethrows -> T {
    let dir = FileManager.default.temporaryDirectory.appendingPathComponent("sc-arc-\(UUID().uuidString)")
    try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: dir) }
    return try body(dir)
}

private var arcCounter = 0

private func arcRequest(_ bytes: Data, in dir: URL, progress: ARCProgress? = nil, cancelled: Bool = false) throws -> ArchiveReadRequest {
    arcCounter += 1
    let source = dir.appendingPathComponent("a\(arcCounter).arc")
    try bytes.write(to: source)
    return ArchiveReadRequest(source: source, format: "arc", root: dir.appendingPathComponent("out\(arcCounter)"),
                              report: { progress?.add($0.unit) }, isCancelled: { cancelled })
}

private final class ARCProgress: @unchecked Sendable {
    private let lock = NSLock()
    private var units: [String] = []
    func add(_ unit: String?) { lock.lock(); if let unit { units.append(unit) }; lock.unlock() }
    var all: [String] { lock.lock(); defer { lock.unlock() }; return units }
}

private func arcRead(_ bytes: Data, in dir: URL) throws -> ArchiveTree { try ARCKit.read(arcRequest(bytes, in: dir)) }

private func arcContent(_ entry: ArchiveTree.Entry) -> Data? { entry.extracted.flatMap { try? Data(contentsOf: $0) } }

private func arcCRC32(_ data: Data) -> UInt32 { ~ACECRC.crc32([UInt8](data)) }

/// Reads a fixture and checks the names and sizes of its files (the stored CRC-16 of each was verified by the reader).
private func arcCheck(_ fixture: ARCFixture, _ label: String, files: [(String, Int)], licenseCRC: Bool = false) {
    arcWork { dir in
        do {
            let tree = try arcRead(fixture.data, in: dir)
            check(tree.entries.map(\.path) == files.map(\.0), "\(label): names \(tree.entries.map(\.path))")
            check(tree.entries.map(\.size) == files.map { Int64($0.1) }, "\(label): sizes \(tree.entries.map(\.size))")
            if licenseCRC, let first = tree.entries.first, let content = arcContent(first) {
                check(arcCRC32(content) == arcLicenseCRC32, "\(label): LICENSE checksum")
            }
        } catch {
            check(false, "\(label): threw \(error)")
        }
    }
}

/// One entry, built by hand: marker, method, 13-byte name, sizes, date, time, CRC-16 of `plain`.
private func arcEntry(method: UInt8, name: String, packed: [UInt8], plain: [UInt8], crc: UInt16? = nil) -> [UInt8] {
    func le(_ v: Int, _ n: Int) -> [UInt8] { (0..<n).map { UInt8(truncatingIfNeeded: v >> (8 * $0)) } }
    var nameBytes = Array(name.utf8)
    nameBytes += [UInt8](repeating: 0, count: 13 - nameBytes.count)
    var bytes: [UInt8] = [0x1A, method] + nameBytes + le(packed.count, 4) + le(0x4256, 2) + le(0x7612, 2) + le(Int(crc ?? ARCKit.CRC16.checksum(plain)), 2)
    if method != 1 { bytes += le(plain.count, 4) }
    return bytes + packed
}

private let arcEnd: [UInt8] = [0x1A, 0x00]

private func arcThrows(_ bytes: [UInt8], _ expected: ArchiveError, _ label: String) {
    arcWork { dir in
        do {
            _ = try arcRead(Data(bytes), in: dir)
            check(false, "\(label): expected \(expected)")
        } catch let error as ArchiveError {
            check(error == expected, "\(label): expected \(expected), got \(error)")
        } catch {
            check(false, "\(label): unexpected \(error)")
        }
    }
}

private struct ARCGenerator {
    var state: UInt64
    mutating func next(_ bound: Int) -> Int {
        state ^= state << 13; state ^= state >> 7; state ^= state << 17
        return Int(state % UInt64(bound))
    }
}

/// Every mutation must extract or throw an ArchiveError; a trap would end the whole run.
private func arcMutations(_ original: Data, label: String, count: Int, seed: UInt64) {
    var generator = ARCGenerator(state: seed | 1)
    var thrown = 0
    arcWork { dir in
        for round in 0..<count {
            var bytes = original
            switch round % 4 {
            case 0: bytes[generator.next(bytes.count)] ^= UInt8(1 << generator.next(8))
            case 1: bytes[generator.next(bytes.count)] = UInt8(generator.next(256))
            case 2: bytes = bytes.prefix(generator.next(bytes.count))
            default:
                // Garble packed data only, so the headers stay believable.
                if bytes.count > 40 { bytes[29 + generator.next(bytes.count - 29)] ^= UInt8(1 << generator.next(8)) }
            }
            do { _ = try arcRead(bytes, in: dir) } catch is ArchiveError { thrown += 1 } catch { check(false, "\(label): non-archive error \(error)") }
            try? FileManager.default.removeItem(at: dir.appendingPathComponent("out\(arcCounter)"))
        }
    }
    check(thrown > count / 4, "\(label): mutations are mostly rejected (\(thrown) of \(count))")
}

func registerArchiveKitARCTests() {
    SelfTest.cases.append(("ArchiveKit.arc.crc16", {
        check(ARCKit.CRC16.checksum(Array("123456789".utf8)) == 0xBB3D, "CRC-16/ARC of 123456789")
    }))

    SelfTest.cases.append(("ArchiveKit.arc.stored", {
        arcCheck(ARCFixtures.stored, "t.arc", files: [("t.txt", 2), ("t2.txt", 2)])
        arcWork { dir in
            guard let tree = try? arcRead(ARCFixtures.stored.data, in: dir), tree.entries.count == 2 else { check(false, "t.arc read"); return }
            check(arcContent(tree.entries[0]) == Data("42".utf8), "content")
            let parts = Calendar(identifier: .gregorian).dateComponents([.year, .month, .day, .hour, .minute, .second], from: tree.entries[0].modified ?? .distantPast)
            check(parts.year == 2013 && parts.month == 2 && parts.day == 22 && parts.hour == 14 && parts.minute == 48 && parts.second == 36, "date \(parts)")
            check(!tree.wasEncrypted && tree.nameEncoding == nil, "flags")
        }
        // Without the end marker the archive is still complete.
        let noEnd = ARCFixtures.stored.data.dropLast(2)
        arcWork { dir in check((try? arcRead(Data(noEnd), in: dir))?.entries.count == 2, "missing end marker is accepted") }
    }))

    SelfTest.cases.append(("ArchiveKit.arc.old-stored-method-1", {
        let plain = Array("old style, no original-size field".utf8)
        let bytes = arcEntry(method: 1, name: "OLD.TXT", packed: plain, plain: plain) + arcEnd
        arcWork { dir in
            guard let tree = try? arcRead(Data(bytes), in: dir), tree.entries.count == 1 else { check(false, "read"); return }
            check(tree.entries[0].path == "OLD.TXT" && arcContent(tree.entries[0]) == Data(plain), "method 1 content")
        }
    }))

    SelfTest.cases.append(("ArchiveKit.arc.packed-run-length", {
        // 'A', then "90 04" (four in all), then "90 00" (a literal 0x90), then 'B'.
        let packed: [UInt8] = [0x41, 0x90, 0x04, 0x90, 0x00, 0x42]
        let plain: [UInt8] = [0x41, 0x41, 0x41, 0x41, 0x90, 0x42]
        let bytes = arcEntry(method: 3, name: "RLE.BIN", packed: packed, plain: plain) + arcEnd
        arcWork { dir in
            guard let tree = try? arcRead(Data(bytes), in: dir), tree.entries.count == 1 else { check(false, "read"); return }
            check(arcContent(tree.entries[0]) == Data(plain), "packed content")
        }
    }))

    SelfTest.cases.append(("ArchiveKit.arc.packed-and-squeezed", {
        arcCheck(ARCFixtures.cpm, "cpm.arc (methods 4 and 3)", files: [("DDTZ.COM", 9984), ("READ.COM", 128)])
    }))

    SelfTest.cases.append(("ArchiveKit.arc.crunched", {
        arcCheck(ARCFixtures.crunch, "crunch.arc", files: [("LICENSE", 11357)], licenseCRC: true)
        arcCheck(ARCFixtures.crunch2, "crunch2.arc", files: [("LICENSE", 11357)], licenseCRC: true)
        arcCheck(ARCFixtures.crunchClear, "crunch_clear.arc (table resets)", files: [("SHIFT1.TXT", 34714)])
    }))

    SelfTest.cases.append(("ArchiveKit.arc.squashed", {
        arcCheck(ARCFixtures.squashed, "squashed.arc", files: [("LICENSE", 11357)], licenseCRC: true)
        arcCheck(ARCFixtures.squashClear, "squash_clear.arc (table resets)", files: [("SHIFT1.TXT", 34714)])
    }))

    SelfTest.cases.append(("ArchiveKit.arc.unsupported-methods", {
        for method: UInt8 in [5, 6, 7, 10, 11, 20, 30] {
            arcThrows(arcEntry(method: method, name: "X.BIN", packed: [1, 2, 3, 4], plain: [1, 2, 3, 4]) + arcEnd,
                      .unsupported("ARC method \(method)"), "method \(method)")
        }
    }))

    SelfTest.cases.append(("ArchiveKit.arc.damaged", {
        let stored = [UInt8](ARCFixtures.stored.data)
        var wrongCRC = stored
        wrongCRC[23] ^= 0x01
        arcThrows(wrongCRC, .damaged("A file’s checksum doesn’t match."), "wrong CRC-16")
        arcThrows(Array(stored.prefix(20)), .damaged("An ARC header is cut short."), "header cut short")
        arcThrows(Array(stored.prefix(30)), .damaged("An ARC archive is cut short."), "data cut short")
        arcThrows([], .damaged("This isn’t an ARC archive."), "empty")
        arcThrows(Array("PK\u{3}\u{4} not an arc".utf8), .damaged("This isn’t an ARC archive."), "other format")
        arcThrows(Array(stored.dropLast(2)) + [0x20, 0x20], .damaged("An ARC entry doesn’t start where expected."), "junk after the last entry")
        var flipped = [UInt8](ARCFixtures.crunch.data)
        flipped[flipped.count / 2] ^= 0x08
        arcWork { dir in
            do { _ = try arcRead(Data(flipped), in: dir); check(false, "flipped LZW bit accepted") } catch is ArchiveError {} catch { check(false, "\(error)") }
        }
        let tooSmall = arcEntry(method: 2, name: "S.BIN", packed: [1, 2], plain: [1, 2, 3, 4]) + arcEnd
        arcThrows(tooSmall, .damaged("A stored file is cut short."), "stored smaller than its size")
    }))

    SelfTest.cases.append(("ArchiveKit.arc.path-traversal", {
        let evil = Array("evil".utf8), fine = Array("fine".utf8)
        let bytes = arcEntry(method: 2, name: "..\\..\\e.txt", packed: evil, plain: evil) + arcEntry(method: 2, name: "SUB\\OK.TXT", packed: fine, plain: fine) + arcEnd
        arcWork { dir in
            do {
                let request = try arcRequest(Data(bytes), in: dir)
                let extractor = try request.extractor(windowsSeparators: true)
                let tree = try ARCKit.read(request, into: extractor)
                check(tree.entries.map(\.path) == ["SUB/OK.TXT"], "kept \(tree.entries.map(\.path))")
                check(extractor.unsafeNames == 1, "one name counted as skipped, got \(extractor.unsafeNames)")
                check(!FileManager.default.fileExists(atPath: request.root.deletingLastPathComponent().appendingPathComponent("e.txt").path), "nothing above the root")
                check(!FileManager.default.fileExists(atPath: request.root.appendingPathComponent("e.txt").path), "nothing renamed into the root")
            } catch { check(false, "threw \(error)") }
        }
    }))

    SelfTest.cases.append(("ArchiveKit.arc.empty-file-and-names", {
        let bytes = arcEntry(method: 2, name: "EMPTY.TXT", packed: [], plain: []) + arcEntry(method: 2, name: "", packed: [7], plain: [7]) + arcEnd
        arcWork { dir in
            guard let tree = try? arcRead(Data(bytes), in: dir) else { check(false, "read"); return }
            check(tree.entries.map(\.path) == ["EMPTY.TXT", "file0001"], "paths \(tree.entries.map(\.path))")
            check(tree.entries.first?.size == 0, "empty file")
        }
    }))

    SelfTest.cases.append(("ArchiveKit.arc.progress-and-cancel", {
        arcWork { dir in
            let progress = ARCProgress()
            do {
                _ = try ARCKit.read(arcRequest(ARCFixtures.cpm.data, in: dir, progress: progress))
                check(progress.all.first == "File 1 of 2" && progress.all.contains("File 2 of 2"), "progress \(progress.all)")
                _ = try ARCKit.read(arcRequest(ARCFixtures.cpm.data, in: dir, cancelled: true))
                check(false, "cancellation ignored")
            } catch ArchiveError.cancelled {
            } catch { check(false, "threw \(error)") }
        }
    }))

    SelfTest.cases.append(("ArchiveKit.arc.mutations-never-trap", {
        let all: [(String, ARCFixture)] = [
            ("stored", ARCFixtures.stored), ("cpm", ARCFixtures.cpm), ("crunch", ARCFixtures.crunch),
            ("crunch2", ARCFixtures.crunch2), ("squashed", ARCFixtures.squashed),
        ]
        for (index, item) in all.enumerated() {
            arcMutations(item.1.data, label: item.0, count: 300, seed: UInt64(0x51ED_270B &+ index &* 6151))
        }
    }))
}
